from qb import q, write

CS = ["backend-developer", "full-stack-developer", "python-developer", "frontend-developer"]
ITEMS = [
    q("java", "easy", ["jvm"], "What are the JDK, JRE and JVM, and what does the garbage collector do?", "The JVM runs compiled bytecode, the JRE is the JVM with the standard libraries and the JDK adds development tools such as the compiler. The garbage collector frees objects that are no longer reachable so the programmer does not free memory manually.", ["JDK contains JRE contains JVM", "Bytecode portability", "Automatic memory reclaim"], ["Can you force garbage collection?"]),
    q("java", "medium", ["collections"], "How does HashMap work internally and why must you implement equals and hashCode together?", "HashMap uses the key's hashCode to choose a bucket and equals to find the matching key inside it. If equal objects have different hash codes, lookups fail, so the two methods must agree, and keys should be immutable.", ["Buckets by hash code", "equals resolves collisions", "Consistent contract"], ["What happens when many keys collide?"]),
    q("java", "medium", ["streams"], "What are Java streams and how would you group a list of orders by customer and sum their amounts?", "Streams process collections with a pipeline of operations such as filter, map and collect. Use Collectors.groupingBy on the customer with Collectors.summingDouble or summingInt on the amount.", ["Pipeline of operations", "groupingBy collector", "Downstream summing"], ["When is a plain loop clearer?"]),
    q("java", "hard", ["concurrency"], "What is the difference between synchronized, volatile and the java.util.concurrent classes and when do you use each?", "synchronized gives mutual exclusion and visibility for a block, volatile only guarantees visibility of a single variable, and the concurrent package provides tested tools such as ConcurrentHashMap, atomic classes and executors. Prefer the higher-level tools.", ["Mutual exclusion vs visibility", "Atomic classes and concurrent collections", "Prefer high-level tools"], ["Why is count++ not thread-safe even on a volatile field?"]),
    q("java", "medium", ["spring"], "What is the difference between Spring and Spring Boot and what does @Transactional do?", "Spring is the core framework with dependency injection and many modules, while Spring Boot adds auto-configuration, an embedded server and starters so applications run with little setup. @Transactional wraps a method in a database transaction that commits on success and rolls back on a runtime exception.", ["Boot simplifies setup", "Dependency injection", "Transaction boundaries and rollback"], ["Why can a self-call bypass @Transactional?"]),
    q("java", "hard", ["jpa"], "What is the N+1 problem in JPA or Hibernate and how do you fix it?", "Loading a list of entities and then touching a lazy relation runs one query per row. Fix it with join fetch, entity graphs or batch fetching, or by selecting a projection that contains only what is needed.", ["One query per row", "Join fetch or entity graph", "Projections"], ["How do you detect it?"]),
    q("csharp", "medium", ["dotnet"], "What are the main differences between Java and C# that a developer moving between them would notice?", "Both are object-oriented, garbage collected and strongly typed. C# adds features such as properties, LINQ, async/await built into the language and value-type structs, while Java emphasises the JVM ecosystem, checked exceptions and a large framework landscape such as Spring.", ["Shared concepts", "Properties, LINQ, async in C#", "Checked exceptions and Spring in Java"], ["Which would you choose for a new SaaS backend and why?"]),
    q("csharp", "medium", ["dotnet"], "How would you implement authentication and authorisation in an ASP.NET Core SaaS application with several tenants?", "Authenticate users with tokens or an identity provider, store the tenant id in the claims, filter every query by the tenant and check roles and policies on endpoints. Test that one tenant can never read another's data.", ["Tokens and claims", "Tenant filter on every query", "Tests for isolation"], ["Where would you enforce the tenant filter to avoid mistakes?"]),
    q("saas", "medium", ["multi-tenancy"], "What are the ways to separate customers' data in a multi-tenant SaaS database and what are their trade-offs?", "Options are a separate database per tenant, a schema per tenant or a shared schema with a tenant column. Separate databases give the strongest isolation at higher cost and management effort, while a shared schema is cheapest but needs strict filtering.", ["Three isolation models", "Isolation vs cost", "Strict filtering for shared tables"], ["How would you migrate one big customer to its own database?"]),
    q("saas", "hard", ["scalability"], "A SaaS product's reports slow down as customers grow. How do you scale without rewriting everything?", "Measure to find the bottleneck, add indexes and caching, move reports to read replicas or a separate analytics store, pre-aggregate data, run heavy jobs asynchronously and scale stateless services horizontally.", ["Measure first", "Replicas and pre-aggregation", "Asynchronous heavy jobs"], ["How do you stop one customer slowing others?"]),
    q("saas", "medium", ["billing"], "What would you consider when building subscription billing and usage limits?", "Store plans, prices with effective dates and usage records, handle upgrades and prorating, make charging idempotent, keep invoices immutable, reconcile with the payment provider and enforce limits on the server.", ["Plans and usage records", "Idempotent charging", "Reconcile and enforce on the server"], ["How do you handle a failed payment?"]),
    q("sql", "easy", ["sql"], "What is the difference between WHERE and HAVING and between COUNT(*) and COUNT(column)?", "WHERE filters rows before grouping and HAVING filters groups after aggregation. COUNT(*) counts all rows and COUNT(column) counts only rows where the column is not null.", ["Before vs after grouping", "Nulls in COUNT", "Aggregation order"], ["Write a query using both."]),
    q("sql", "medium", ["indexes"], "How do you choose the order of columns in a composite index?", "Put columns used in equality filters first and the range or sort column last, and put the most selective columns early when they are used together. The index only helps queries that use its leading columns.", ["Equality before range", "Leading columns matter", "Check with the query plan"], ["Why does an index on (a, b) not help a filter on b alone?"]),
    q("sql", "hard", ["transactions"], "How do isolation levels and locking affect a busy SaaS application and what would you use by default?", "Higher isolation prevents anomalies but increases blocking and deadlocks. Read committed is a common default, with row-level locks or optimistic concurrency for specific critical updates, and keeping transactions short.", ["Anomalies vs concurrency", "Read committed default", "Short transactions and optimistic locking"], ["When would you use serializable?"]),
    q("api", "medium", ["rest"], "How do you version a public REST API and deprecate old versions without losing customers?", "Use a version in the URL or header, make changes additive when possible, announce deprecations with dates, give migration guides, monitor who still uses old versions and contact them before retiring it.", ["Versioning scheme", "Additive changes and notice", "Monitor usage"], ["How do webhooks change this problem?"]),
    q("api", "hard", ["reliability"], "How would you make webhook delivery to customers reliable?", "Send events from a queue with signed payloads, retry failures with exponential backoff, record delivery attempts, let customers see and replay failed events and make receivers idempotent with event ids. Disable endpoints that fail for too long.", ["Queue, retries and backoff", "Signed payloads", "Idempotency and replay"], ["How does the customer verify the signature?"]),
    q("cloud", "medium", ["deployment"], "How would you deploy a Java or .NET service with zero downtime?", "Run several instances behind a load balancer and update them gradually with rolling or blue-green deployment, use health checks, keep database changes backward compatible and have a rollback plan.", ["Rolling or blue-green", "Health checks", "Backward-compatible database changes"], ["How do you handle a long-running request during deployment?"]),
    q("cloud", "hard", ["observability"], "How would you monitor a SaaS service and find a problem before customers report it?", "Collect logs, metrics and traces, define service level indicators such as error rate and latency with alerts, add synthetic checks that call key endpoints and review dashboards and incidents regularly.", ["Logs, metrics, traces", "Alerts on SLIs", "Synthetic checks"], ["How do you avoid alert fatigue?"]),
    q("oop", "medium", ["solid"], "How do the single responsibility and open/closed principles help a product that adds many customer-specific features?", "A class with one responsibility is easy to change safely, and an open/closed design adds customer-specific behaviour through new classes or configuration instead of editing core code. This avoids a tangle of conditions for each customer.", ["One reason to change", "Extend by adding", "Avoid per-customer conditionals"], ["How would feature flags help?"]),
    q("testing", "medium", ["testing"], "How do you test a feature that behaves differently for each customer's configuration?", "Test the core logic with parameterised tests across representative configurations, add integration tests for the riskiest ones and use contract tests for integrations, keeping configuration data in test fixtures.", ["Parameterised tests", "Representative configurations", "Integration and contract tests"], ["How do you pick representative configurations?"]),
    q("cs-scenario", "medium", ["debugging"], "Scenario: one customer reports that a page is very slow while others are fine. How do you investigate?", "Compare their data size and settings with others, check slow queries and logs for their tenant, reproduce with similar data, fix the cause such as a missing index or heavy configuration, and add monitoring per tenant.", ["Compare data and configuration", "Slow queries for that tenant", "Fix and monitor per tenant"], ["How would you protect other customers meanwhile?"], kind="scenario"),
    q("cs-scenario", "hard", ["design"], "Scenario: design an import feature that lets customers upload a 500,000-row CSV safely.", "Upload the file to storage, validate the structure, process in the background in batches with progress, reject bad rows with a downloadable error report, make the import idempotent and limit size and rate per tenant.", ["Background batch processing", "Error report", "Idempotent and limited"], ["How do you handle a file that is half processed when a server restarts?"], kind="scenario"),
    q("cs-scenario", "easy", ["teamwork"], "Scenario: support asks you for an urgent fix that touches code you do not know. How do you proceed?", "Read the code and its tests, ask the owner or teammates, make the smallest safe change with a test, have it reviewed even when urgent and deploy carefully with monitoring.", ["Understand before changing", "Small change with a test", "Review and monitor"], ["When would you refuse a quick fix?"], kind="scenario"),
    q("git", "easy", ["git"], "What is the difference between merge and rebase and how do you handle a conflict in a long-running feature branch?", "Merge keeps both histories with a merge commit and rebase replays your commits on the updated base for a linear history. For a long branch, integrate the main branch often, resolve conflicts by understanding both changes, run tests and avoid rebasing shared branches.", ["Merge vs rebase", "Integrate often", "Test after resolving"], ["When would you squash commits?"]),
    q("project", "easy", ["projects"], "Describe a project in Java, .NET or a web stack. What did you build yourself, how did you test it and what would you improve?", "A strong answer names the project, your exact part and the technologies, how you tested and handled errors, and an honest improvement such as performance or structure.", ["Own part and stack", "Testing and errors", "Honest improvement"], ["How is it deployed?"], kind="scenario", roles=CS),
]


def build():
    return write("contour-software", CS, ITEMS)


if __name__ == "__main__":
    build()
